  INSERT INTO financial_snapshot (msme_id, reporting_period, revenue, total_receivables, overdue_receivables, credit_used, submitted_by_user_id, submitted_at, created_at, updated_at)
    VALUES (v_msme, DATE '2022-10-01', 1003770.69, 582187.00, 104793.66, 957000.00, v_rep, TIMESTAMP '2022-10-29 08:00:00', TIMESTAMP '2022-10-29 08:00:00', TIMESTAMP '2022-10-29 08:00:00') RETURNING snapshot_id INTO v_snapshots(49);
