    VALUES (v_msme, 3, 13, 30, 70, 'APPROVED', v_rm, TIMESTAMP '2024-09-21 00:00:00', v_admin, TIMESTAMP '2024-09-22 00:00:00', 'Synthetic annual threshold version; demo policy only.') RETURNING threshold_config_id INTO v_thresholds(23);
