-- SEED26 - Demo Business 014 / collections_stress
DECLARE
  TYPE id_map IS TABLE OF NUMBER INDEX BY PLS_INTEGER;
  v_thresholds id_map;
  v_snapshots id_map;
  v_assessments id_map;
  v_indicators id_map;
  v_warnings id_map;
  v_interventions id_map;
  v_reviews id_map;
  v_msme NUMBER; v_rm NUMBER; v_admin NUMBER; v_rep NUMBER; v_has_effective NUMBER;
BEGIN
  SELECT user_id INTO v_rm FROM app_user WHERE email = 'seed26.rm04@example.test';
  SELECT user_id INTO v_admin FROM app_user WHERE email = 'seed26.admin02@example.test';
  SELECT COUNT(*) INTO v_has_effective FROM user_tab_columns WHERE table_name = 'THRESHOLD_CONFIG' AND column_name = 'EFFECTIVE_FROM';
  INSERT INTO msme (business_name, sector, contact_name, sanctioned_credit_limit, consent_status, assigned_rm_id, is_active, created_at, updated_at)
    VALUES ('SEED26 - Demo Business 014', 'Logistics', 'Seed Contact 014', 2550000.00, 'GRANTED', v_rm, 'Y', TIMESTAMP '2022-09-16 09:00:00', TIMESTAMP '2022-09-16 09:00:00') RETURNING msme_id INTO v_msme;
  INSERT INTO app_user (name, email, password_hash, role, msme_id, account_status, created_at, updated_at)
    VALUES ('Seed Representative 014', 'seed26.rep014@example.test', '$2a$12$mvaKEsCz6jNtb2ZaJkeN7OHIjapiR5bcFzJAGa.gF91.tN1u/Q57m', 'MSME_REP', v_msme, 'ACTIVE', TIMESTAMP '2022-09-17 09:00:00', TIMESTAMP '2022-09-17 09:00:00') RETURNING user_id INTO v_rep;
  INSERT INTO threshold_config (msme_id, version_no, revenue_decline_pct, overdue_receivable_pct, credit_utilisation_pct, status, proposed_by_user_id, proposed_at, reviewed_by_user_id, reviewed_at, review_reason)
    VALUES (v_msme, 1, 15, 34, 70, 'APPROVED', v_rm, TIMESTAMP '2022-09-21 00:00:00', v_admin, TIMESTAMP '2022-09-22 00:00:00', 'Synthetic annual threshold version; demo policy only.') RETURNING threshold_config_id INTO v_thresholds(53);
  IF v_has_effective = 1 THEN
    EXECUTE IMMEDIATE 'UPDATE threshold_config SET effective_from = :1 WHERE threshold_config_id = :2'
      USING TIMESTAMP '2022-10-01 00:00:00', v_thresholds(53);
  END IF;
  INSERT INTO threshold_config (msme_id, version_no, revenue_decline_pct, overdue_receivable_pct, credit_utilisation_pct, status, proposed_by_user_id, proposed_at, reviewed_by_user_id, reviewed_at, review_reason)
    VALUES (v_msme, 2, 15, 34, 70, 'APPROVED', v_rm, TIMESTAMP '2023-09-21 00:00:00', v_admin, TIMESTAMP '2023-09-22 00:00:00', 'Synthetic annual threshold version; demo policy only.') RETURNING threshold_config_id INTO v_thresholds(54);
  IF v_has_effective = 1 THEN
    EXECUTE IMMEDIATE 'UPDATE threshold_config SET effective_from = :1 WHERE threshold_config_id = :2'
