  SELECT user_id INTO v_rm FROM app_user WHERE email = 'seed26.rm05@example.test';
  SELECT user_id INTO v_admin FROM app_user WHERE email = 'seed26.admin01@example.test';
  SELECT COUNT(*) INTO v_has_effective FROM user_tab_columns WHERE table_name = 'THRESHOLD_CONFIG' AND column_name = 'EFFECTIVE_FROM';
