  INSERT INTO threshold_config (msme_id, version_no, revenue_decline_pct, overdue_receivable_pct, credit_utilisation_pct, status, proposed_by_user_id, proposed_at, reviewed_by_user_id, reviewed_at, review_reason)
    VALUES (v_msme, 4, 15, 34, 70, 'APPROVED', v_rm, TIMESTAMP '2025-09-21 00:00:00', v_admin, TIMESTAMP '2025-09-22 00:00:00', 'Synthetic annual threshold version; demo policy only.') RETURNING threshold_config_id INTO v_thresholds(152);
