-- Fail before commit if the batch is incomplete or relationships do not match.
DECLARE
  v_count NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_count FROM app_user WHERE email LIKE 'seed26.%@example.test';
  IF v_count <> 62 THEN RAISE_APPLICATION_ERROR(-20010, 'Unexpected SEED26 row count for app_user'); END IF;
  DBMS_OUTPUT.PUT_LINE('app_user: ' || TO_CHAR(v_count));
  SELECT COUNT(*) INTO v_count FROM msme WHERE business_name LIKE 'SEED26 - Demo Business %';
  IF v_count <> 50 THEN RAISE_APPLICATION_ERROR(-20010, 'Unexpected SEED26 row count for msme'); END IF;
  DBMS_OUTPUT.PUT_LINE('msme: ' || TO_CHAR(v_count));
  SELECT COUNT(*) INTO v_count FROM threshold_config WHERE msme_id IN (SELECT msme_id FROM msme WHERE business_name LIKE 'SEED26 - Demo Business %');
  IF v_count <> 200 THEN RAISE_APPLICATION_ERROR(-20010, 'Unexpected SEED26 row count for threshold_config'); END IF;
  DBMS_OUTPUT.PUT_LINE('threshold_config: ' || TO_CHAR(v_count));
  SELECT COUNT(*) INTO v_count FROM financial_snapshot WHERE msme_id IN (SELECT msme_id FROM msme WHERE business_name LIKE 'SEED26 - Demo Business %');
  IF v_count <> 2400 THEN RAISE_APPLICATION_ERROR(-20010, 'Unexpected SEED26 row count for financial_snapshot'); END IF;
  DBMS_OUTPUT.PUT_LINE('financial_snapshot: ' || TO_CHAR(v_count));
  SELECT COUNT(*) INTO v_count FROM risk_assessment WHERE msme_id IN (SELECT msme_id FROM msme WHERE business_name LIKE 'SEED26 - Demo Business %');
  IF v_count <> 2400 THEN RAISE_APPLICATION_ERROR(-20010, 'Unexpected SEED26 row count for risk_assessment'); END IF;
  DBMS_OUTPUT.PUT_LINE('risk_assessment: ' || TO_CHAR(v_count));
  SELECT COUNT(*) INTO v_count FROM assessment_indicator_result WHERE assessment_id IN (SELECT assessment_id FROM risk_assessment WHERE msme_id IN (SELECT msme_id FROM msme WHERE business_name LIKE 'SEED26 - Demo Business %'));
  IF v_count <> 7200 THEN RAISE_APPLICATION_ERROR(-20010, 'Unexpected SEED26 row count for assessment_indicator_result'); END IF;
  DBMS_OUTPUT.PUT_LINE('assessment_indicator_result: ' || TO_CHAR(v_count));
  SELECT COUNT(*) INTO v_count FROM warning WHERE assessment_id IN (SELECT assessment_id FROM risk_assessment WHERE msme_id IN (SELECT msme_id FROM msme WHERE business_name LIKE 'SEED26 - Demo Business %'));
  IF v_count <> 93 THEN RAISE_APPLICATION_ERROR(-20010, 'Unexpected SEED26 row count for warning'); END IF;
  DBMS_OUTPUT.PUT_LINE('warning: ' || TO_CHAR(v_count));
  SELECT COUNT(*) INTO v_count FROM intervention WHERE warning_id IN (SELECT warning_id FROM warning WHERE assessment_id IN (SELECT assessment_id FROM risk_assessment WHERE msme_id IN (SELECT msme_id FROM msme WHERE business_name LIKE 'SEED26 - Demo Business %')));
  IF v_count <> 250 THEN RAISE_APPLICATION_ERROR(-20010, 'Unexpected SEED26 row count for intervention'); END IF;
  DBMS_OUTPUT.PUT_LINE('intervention: ' || TO_CHAR(v_count));
  SELECT COUNT(*) INTO v_count FROM follow_up_review WHERE intervention_id IN (SELECT intervention_id FROM intervention WHERE warning_id IN (SELECT warning_id FROM warning WHERE assessment_id IN (SELECT assessment_id FROM risk_assessment WHERE msme_id IN (SELECT msme_id FROM msme WHERE business_name LIKE 'SEED26 - Demo Business %'))));
  IF v_count <> 982 THEN RAISE_APPLICATION_ERROR(-20010, 'Unexpected SEED26 row count for follow_up_review'); END IF;
  DBMS_OUTPUT.PUT_LINE('follow_up_review: ' || TO_CHAR(v_count));
  SELECT COUNT(*) INTO v_count FROM activity_log WHERE msme_id IN (SELECT msme_id FROM msme WHERE business_name LIKE 'SEED26 - Demo Business %');
  IF v_count <> 6343 THEN RAISE_APPLICATION_ERROR(-20010, 'Unexpected SEED26 row count for activity_log'); END IF;
  DBMS_OUTPUT.PUT_LINE('activity_log: ' || TO_CHAR(v_count));
  SELECT COUNT(*) INTO v_count FROM financial_snapshot s
    JOIN msme m ON m.msme_id = s.msme_id
    WHERE m.business_name LIKE 'SEED26 - Demo Business %'
      AND s.reporting_period NOT BETWEEN DATE '2022-10-01' AND DATE '2026-09-01';
  IF v_count <> 0 THEN RAISE_APPLICATION_ERROR(-20011, 'Unexpected reporting period'); END IF;
  SELECT COUNT(*) INTO v_count FROM (
    SELECT m.msme_id FROM msme m LEFT JOIN financial_snapshot s ON s.msme_id = m.msme_id
    WHERE m.business_name LIKE 'SEED26 - Demo Business %'
    GROUP BY m.msme_id HAVING COUNT(s.snapshot_id) <> 48
      OR MIN(s.reporting_period) <> DATE '2022-10-01'
      OR MAX(s.reporting_period) <> DATE '2026-09-01');
  IF v_count <> 0 THEN RAISE_APPLICATION_ERROR(-20012, 'A business does not have 48 monthly snapshots'); END IF;
  SELECT COUNT(*) INTO v_count FROM risk_assessment a
    JOIN financial_snapshot s ON s.snapshot_id = a.snapshot_id
    JOIN threshold_config t ON t.threshold_config_id = a.threshold_config_id
    JOIN msme m ON m.msme_id = a.msme_id
    WHERE m.business_name LIKE 'SEED26 - Demo Business %'
      AND (s.msme_id <> a.msme_id OR t.msme_id <> a.msme_id);
  IF v_count <> 0 THEN RAISE_APPLICATION_ERROR(-20013, 'Cross-business assessment reference'); END IF;
END;
/
COMMIT;
PROMPT SEED26 complete. Existing records were preserved.

SELECT m.msme_id, m.business_name, u.email AS assigned_rm_email
FROM msme m JOIN app_user u ON u.user_id = m.assigned_rm_id
WHERE m.business_name LIKE 'SEED26 - Demo Business %'
ORDER BY m.business_name;
